import{_ as s,o as i,c as o,ah as a}from"./chunks/framework.Q09Tu2Li.js";const n="/projects/rosorin-pro/en/latest/assets/image3.BAbPlWG0.png",l="/projects/rosorin-pro/en/latest/assets/image6.CByXnmeI.png",e="data:image/png;base64,",r="/projects/rosorin-pro/en/latest/assets/image10.vPXKW0qr.png",h="/projects/rosorin-pro/en/latest/assets/image12.C-oLo2Gk.png",d="/projects/rosorin-pro/en/latest/assets/image1.bRFzUb2t.png",p="/projects/rosorin-pro/en/latest/assets/image2.C0K57vrR.png",f=JSON.parse('{"title":"11. Group Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/11_Group_Control.md","filePath":"docs/11_Group_Control.md"}'),c={name:"docs/11_Group_Control.md"};function g(u,t,m,b,k,y){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="_11-group-control" tabindex="-1">11. Group Control <a class="header-anchor" href="#_11-group-control" aria-label="Permalink to &quot;11\\. Group Control&quot;">​</a></h1><h2 id="_11-1-leader-follower-configuration" tabindex="-1">11.1 Leader-Follower Configuration <a class="header-anchor" href="#_11-1-leader-follower-configuration" aria-label="Permalink to &quot;11.1 Leader-Follower Configuration&quot;">​</a></h2><h3 id="_11-1-1-preparation" tabindex="-1">11.1.1 Preparation <a class="header-anchor" href="#_11-1-1-preparation" aria-label="Permalink to &quot;11.1.1 Preparation&quot;">​</a></h3><ol><li><p>Prepare at least two robots.</p></li><li><p>Refer to the section <a href="https://wiki.hiwonder.com/projects/rosorin-pro/en/latest/docs/1_ROSOrin_Pro_User_Manual.html#development-environment-setup" target="_blank" rel="noreferrer">1.7 Development Environment Setup</a> in the user manual for instructions on downloading and installing the remote connection tool, NoMachine.</p></li></ol><h3 id="_11-1-2-working-principle" tabindex="-1">11.1.2 Working Principle <a class="header-anchor" href="#_11-1-2-working-principle" aria-label="Permalink to &quot;11.1.2 Working Principle&quot;">​</a></h3><p>By configuring the leader and follower robots on the same network and utilizing different namespaces, the broadcast program sends speed commands to the follower robot, achieving group control.</p><h3 id="_11-1-3-network-configuration" tabindex="-1">11.1.3 Network Configuration <a class="header-anchor" href="#_11-1-3-network-configuration" aria-label="Permalink to &quot;11.1.3 Network Configuration&quot;">​</a></h3><ul><li><strong>Configuring the Leader Robot Network</strong></li></ul><ol><li>First, select one robot as the leader, power it on, and then remotely connect to its system desktop.</li></ol><ol start="2"><li>Open a terminal and input the following command to navigate to the directory where the file is located.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_manager</span></span></code></pre></div><ol start="3"><li>Next, input the command below to open the Wi-Fi configuration file using the vim editor.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><ol start="4"><li>Press the <strong>i</strong> key to enter edit mode. Locate the two lines of code highlighted in the image below and modify the leader hotspot password.</li></ol><img loading="lazy" height="137" width="1268" class="common_img" src="'+n+'"><ol start="5"><li>Once the changes are complete, press the <strong>Esc</strong> key to exit the edit mode. Then input <code>:wq</code> to save the changes and exit.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><ol start="6"><li>Finally, input the command to reboot the leader robot.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><ol start="7"><li>After the leader robot restarts, when reconnecting to the Wi-Fi, enter the Wi-Fi password <strong>hiwonder</strong>.</li></ol><ul><li><strong>Configuring the Follower Robot Network</strong></li></ul><ol><li>Power on the follower robot and remotely connect to its system desktop.</li></ol><ol start="2"><li>Open a terminal and input the following command to navigate to the directory where the file is located.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_manager</span></span></code></pre></div><ol start="3"><li>Next, input the command below to open the Wi-Fi configuration file using the vim editor.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><ol start="4"><li>Press the <strong>i</strong> key to enter the edit mode, then modify the Wi-Fi name and password lines as shown in the image below. Locate the three highlighted lines of code.</li></ol><img loading="lazy" height="175" width="1268" class="common_img" src="'+l+'"><p>Set the follower robot&#39;s network mode to <strong>2</strong> for LAN mode. <strong>HW-123</strong> and <strong>hiwonder</strong> are the Wi-Fi name and password configured for the leader robot network.</p><ol start="5"><li>Once the changes are complete, press the <strong>Esc</strong> key to exit the edit mode. Then input the command to save and exit.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><ol start="6"><li>Finally, input the command to reboot the robot. This step cannot be skipped!</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>When ROSOrin Pro starts up in LAN mode, it will automatically search for the pre-configured network. During this process, LED2 on the expansion board will blink rapidly, indicating that the system is looking for the network. If no network is found after three consecutive search attempts, ROSOrin Pro will automatically switch to direct connection mode, with LED2 blinking slowly.</strong></p></li><li><p><strong>In the event that ROSOrin Pro cannot find the network in LAN mode and switches to direct connection mode, the wifi_conf.py file will not be updated automatically. It will still contain the LAN configuration, and if not manually adjusted, ROSOrin Pro will attempt to connect in LAN mode again on the next boot.</strong></p></li><li><p><strong>Once the follower robot is set to LAN mode, ensure that the leader robot is powered on and its network is properly configured, so that its hotspot can be detected before the follower starts up. If the follower robot fails to detect the leader&#39;s hotspot within a certain time frame, it will automatically switch to direct connection mode, which may prevent the leader and follower robots from establishing a network connection.</strong></p></li></ul></div><h3 id="_11-1-4-configuring-environment-variables" tabindex="-1">11.1.4 Configuring Environment Variables <a class="header-anchor" href="#_11-1-4-configuring-environment-variables" aria-label="Permalink to &quot;11.1.4 Configuring Environment Variables&quot;">​</a></h3><ul><li><strong>For Leader Robot</strong></li></ul><ol><li><p>Select one ROSOrin Pro as the leader robot and power it on. Then, remotely connect to the desktop via NoMachine.</p></li><li><p>Click the terminal icon <img loading="lazy" height="29" width="31" class="common_img" src="'+e+'" style="display:inline;vertical-align:middle;"> in the system desktop to open a command-line window.</p></li><li><p>Ensure that the leader robot has a USB receiver for the wireless controller connected.</p></li></ol><ol start="4"><li>Input the command to disable the auto-start feature and press <strong>Enter</strong>.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="5"><li>Input the command to open the file and configure the environment variables for the leader robot.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/ubuntu/ros2_ws/.typerc</span></span></code></pre></div><ol start="6"><li>Press the <strong>i</strong> key to enter edit mode, then set both the leader and follower configurations, setting the leader robot as <code>robot_1</code>.</li></ol><img loading="lazy" height="64" width="374" class="common_img" src="'+r+'"><ol start="7"><li>Once the changes are complete, press the <strong>Esc</strong> key to exit the edit mode. Then input the command to save and exit.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><ol start="8"><li>Finally, input the following command to complete the leader robot configuration.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.zshrc</span></span></code></pre></div><ul><li><strong>For Follower Robot</strong></li></ul><ol><li><p>First, connect to the Wi-Fi network created by the leader robot on the app. Once connected, search for the follower robot. The vehicle icon will appear in the app, and by long-pressing the screen, the follower robot’s IP address will be displayed. Refer to section <a href="https://wiki.hiwonder.com/projects/rosorin-pro/en/latest/docs/1_ROSOrin_Pro_User_Manual.html#lan-mode-connection-optional" target="_blank" rel="noreferrer">1.5.2.2 LAN Mode Connection (Optional)</a> in the user manual for guidance on using this IP address.</p></li><li><p>Click the terminal icon <img loading="lazy" height="29" width="31" class="common_img" src="'+e+'" style="display:inline;vertical-align:middle;"> on the system desktop to open a command-line window.</p></li></ol><ol start="3"><li>Input the command to disable the auto-start service and press <strong>Enter</strong>.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="4"><li>Input the command to open the file and configure the environment variables for the follower robot.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/ubuntu/ros2_ws/.typerc</span></span></code></pre></div><ol start="5"><li>Press the <strong>i</strong> key to enter edit mode, then open the leader-follower settings and set the follower robot&#39;s HOST variable to <code>robot_2</code>.</li></ol><img loading="lazy" height="68" width="355" class="common_img" src="'+h+'"><ol start="6"><li>Once the changes are complete, press the <strong>Esc</strong> key to exit the edit mode. Then input the command to save and exit.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><ol start="7"><li>Finally, run the command to refresh the environment variables.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.zshrc</span></span></code></pre></div><h2 id="_11-2-group-control-start-up-steps-and-operations" tabindex="-1">11.2 Group Control Start-up Steps and Operations <a class="header-anchor" href="#_11-2-group-control-start-up-steps-and-operations" aria-label="Permalink to &quot;11.2 Group Control Start-up Steps and Operations&quot;">​</a></h2><h3 id="_11-2-1-synchronizing-time" tabindex="-1">11.2.1 Synchronizing Time <a class="header-anchor" href="#_11-2-1-synchronizing-time" aria-label="Permalink to &quot;11.2.1 Synchronizing Time&quot;">​</a></h3><ol><li>On the leader robot terminal, enter the command to check the current time.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>date</span></span></code></pre></div><img loading="lazy" height="40" width="706" class="common_img" src="'+d+'"><ol start="2"><li>Then, open the follower robot and enter the command to synchronize the system time. Note: The time on the leader robot should be used as the reference.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo date -s &quot;2025-8-20 10:50:03&quot;</span></span></code></pre></div><img loading="lazy" height="43" width="702" class="common_img" src="'+p+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>If there is a noticeable synchronization issue when controlling with the wireless controller later, it is likely due to the system time mismatch between the leader and follower robots. If this happens, return to this step to resynchronize.</strong></p></li><li><p><strong>When using the date command to update the follower’s time with the leader’s time, the process will take some time to execute. As a result, by the time the time is updated on the follower robot, the leader robot’s actual time will have advanced slightly. To avoid errors during this operation, after getting the time from the leader robot, use a stopwatch or manually track the seconds. The time entered into the follower robot&#39;s terminal should be the leader robot’s time plus the seconds counted on the stopwatch.</strong></p></li><li><p><strong>After synchronizing the time on both the leader and follower robots, enter the date command on both terminals with a short interval between them, and check the system times displayed. If the difference is minimal, synchronization can be considered successful.</strong></p></li></ul></div><h3 id="_11-2-2-program-execution" tabindex="-1">11.2.2 Program Execution <a class="header-anchor" href="#_11-2-2-program-execution" aria-label="Permalink to &quot;11.2.2 Program Execution&quot;">​</a></h3><ol><li>On the leader robot, open three terminals and enter the commands to run the following programs in sequence.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi_controller.launch.py</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ros2_ws/src/multi/launch/joystick_control_multi.py</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> joy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> joy_node</span></span></code></pre></div><ol start="2"><li>On the follower robot, enter the command to execute the following program.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi_controller.launch.py</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Each time the robots are powered on to run group control, ensure that the auto-start service is disabled on both the leader and follower robots, and that the system time is synchronized.</strong></p></div><h3 id="_11-2-3-group-control-operation" tabindex="-1">11.2.3 Group Control Operation <a class="header-anchor" href="#_11-2-3-group-control-operation" aria-label="Permalink to &quot;11.2.3 Group Control Operation&quot;">​</a></h3><ol><li><p>Push the switch on the wireless controller to the <strong>ON</strong> position. At this point, both the red and green LEDs on the wireless controller will blink simultaneously.</p></li><li><p>Wait a few seconds for the robot and wireless controller to pair automatically. Once pairing is successful, the green LED will remain solid while the red LED turns off.</p></li><li><p>The wireless controller is now connected to the leader robot. Press the <strong>START</strong> button, and both robots&#39; buzzers will emit a beep sound.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Gently pushing the joysticks in any direction allows low-speed movement.</strong></p></div><table tabindex="0"><thead><tr><th>Key</th><th>Function</th><th>Description</th></tr></thead><tbody><tr><td>START</td><td>Stop and reset the robot</td><td>Press</td></tr><tr><td>Left Joystick Up</td><td>Move forward</td><td>Push</td></tr><tr><td>Left Joystick Down</td><td>Move backward</td><td>Push</td></tr><tr><td>Left Joystick Left</td><td>Strafe left for the Mecanum &amp; differential chassis</td><td>Push</td></tr><tr><td>Left Joystick Right</td><td>Strafe right for the Mecanum &amp; differential chassis</td><td>Push</td></tr><tr><td>Right Joystick Left</td><td>Turn left</td><td>Push</td></tr><tr><td>Right Joystick Right</td><td>Turn right</td><td>Push</td></tr></tbody></table>',80)])])}const w=s(c,[["render",g]]);export{f as __pageData,w as default};
